using System.Diagnostics; using CodexMultipleAccounts.Core.Launching;
namespace CodexMultipleAccounts.App.Terminal;
public sealed class ExternalTerminalLauncher { public void Launch(CodexLaunchSpec spec){ ProcessStartInfo psi; if(OperatingSystem.IsWindows()){ var command=$"set \"CODEX_HOME={spec.Environment["CODEX_HOME"]}\" && cd /d \"{spec.WorkingDirectory}\" && codex"; psi=new("cmd.exe",$"/k {command}"){UseShellExecute=true}; } else { var shell=Environment.GetEnvironmentVariable("SHELL")??"/bin/sh"; var command=$"export CODEX_HOME='{Escape(spec.Environment["CODEX_HOME"])}'; cd '{Escape(spec.WorkingDirectory)}'; exec codex"; if(OperatingSystem.IsMacOS()) psi=new("open",$"-a Terminal --args {shell} -lc \"{command}\""){UseShellExecute=false}; else psi=new("x-terminal-emulator",$"-e {shell} -lc \"{command}\""){UseShellExecute=false}; } Process.Start(psi); } private static string Escape(string s)=>s.Replace("'","'\\''"); }
